/* ================= 开发流程 · 各阶段产出物模板（renderPipeDetail 按阶段消费 · 2026-10-07） ================= */
pipelineTpl: [
  { no: 1, t: `选题评估表 · 立项前逐项填写`, text: `【选题评估表】复制后逐项填写
题材赛道：男频（战神/逆袭/玄幻/系统流/末世…）｜女频（甜宠/萌宝/穿越/重生复仇）
IP来源：官方授权（抖音IP库50万部/阅文10万部/书旗5万部/番茄版权中台）□ ——私改网文=侵权
对标爆款：DataEye/红果热榜查3部，记录名称+播放量：____
选本三件事：人物能被记住□ 情节能往前走□ 画面能做出来□（三条全过再立项）
三本账：单条综合成本__元 / 抽卡可用率目标≥30%□ / 万播单价5-30元（红果已砍保底）
审核预检：软色情□ 暴力血腥□ 未成年人保护□（命中即换题材）
结论：立项□ / 淘汰□　理由：____` },
  { no: 2, t: `网文改编拆书单`, text: `【网文改编拆书单】四步拆书 → 三层产物
①拆梗概：关联原文30章逐章拆剧情梗概
②提元素：核心人设录入角色卡（40-80字描述卡），冲突链单独列出
③分集：每集标注 冲突 + 钩子（黄金3秒）+ 反转（45-60秒处）+ 结尾卡点
④场次化：场景/人物/动作/对白四要素，动作描述要"可稳定生成"（抖音2026-08-03新审核重点）
三层产物缺一不可：分集大纲 → 场次化剧本 → 人物与场景资产清单（直接喂画布当锚点）
钩子配平：情绪钩30-40% / 悬念钩20-30% / 危机钩10-20% / 信息钩10-20%
开场15秒三要素：身份错位 + 利益威胁 + 视觉冲击
反转三模式：身份反转 / 利益反转 / 关系反转——必须回收伏笔（伏笔-反转-解密闭环）` },
  { no: 3, t: `分镜表 · 11字段表头与填写口径`, text: `【分镜表11字段】Excel/飞书多维表表头，一行=一镜
镜头号 | 景别 | 时长(秒) | 画面描述 | 台词 | 角色 | 场景/道具 | 运镜 | 生成方式 | 转场 | 情绪点/钩子
填写口径：
· 单集2分钟约40-60镜，平均镜头<2秒，反转点镜头可短至0.5秒
· 每镜运镜≤2种（方向+速度+目的齐全），堆三个以上必漂移
· 生成方式三选一：文生图 / 图生视频 / 视频直出（下游工具按此列批量消费）
· 一个镜头塞两个以上事件就要拆镜；相邻镜号避免相同景别` },
  { no: 4, t: `角色描述卡 + LoRA训练速查`, text: `【角色描述卡】40-80字，定稿后一字不改复制粘贴
结构：发型+发色+瞳色+服装+标志特征（例：黑色长发低马尾/深棕瞳/白色立领风衣+银色怀表/左眉尾疤痕）
【角色LoRA训练速查】（LiblibAI在线训练约10-50元/次，含打标约30分钟-1小时）
· 数据集：30-100张（60+较稳），多角度/多光照/多表情/多景别；构图分布 特写:半身:全身≈4:4:2【经验推断】
· 正则化图：训练集的5%-10%；自动打标+固定触发词（如 myrole）
· 参数基线：视频/大模型角色LoRA 学习率1e-6、步数2000-3000；Z-Image实测250步见效（Rank 32、权重0.75）
· 训练中途定期出样本图肉眼监控；效果不足→加epoch或查数据集质量` },
  { no: 5, t: `抽卡提示词结构公式`, text: `【抽卡提示词结构公式】团队统一模板，防风格漂移
固定前缀(画风/质量词) + 风格词 + 主体描述 + 镜头语言 + 光影氛围 + 画质后缀
· 镜头语言量化：焦段（24mm环境/35mm叙事/85mm特写）+ 景别 + 角度（平/俯/仰/过肩/Dutch）
· 用光比数据替代"柔和"等主观词；"全身镜头"这类无效指令→改成构图与画面边界的显式描述
· 每集/每角色固定同一段前缀+风格词，只改镜头与动作段
· 参考图挂载：多图注明用途（"男人@图片1 下班后疲惫地走在走廊"）；首尾帧两帧关联性不要太远
· 抽卡可用率<30%：先改模板再量产；批量抽卡用 ComfyUI-Lumi-Batcher（字节出品）
· 降本：即梦"样片模式"480P草稿抽卡→原生升清1080P，升清约直出1/8成本，实测15秒档省约38%（3分钟以上不支持）` },
  { no: 6, t: `口型失步排查单`, text: `【口型失步排查单】先贴四模式标签再动手，一次只改一个变量
①固定偏移 → 查音频起点/时间线对齐
②漂移 → 拆短音频（单句约10字、一句一存、文件名标好）
③假动作 → 清呼吸/底噪/BGM，纯人声生成导出后再混
④口形 → 换牙齿部分可见的正脸源图（多源公认第一因）
验收：唇形误差≤3帧合格（约100ms@30fps、120ms@25fps），>5帧观众明显感知需返工
重点测：重音音节、开口音(a/o/e)、闭口音(i/u/ü)、边鼻音(l/n)、唱歌与难词（名字/缩写/数字）
试镜/正式双轨【经验推断】：可灵4.0 Flash（720P/3-20秒/实测约6灵感值/秒）验证运镜节奏；正式版上关键帧/全能参考出成片——Flash不支持关键帧与参考输入` },
  { no: 7, t: `AI配音情绪标注速查`, text: `【AI配音情绪标注速查】
MiniMax Speech 2.6：emotion = happy/sad/angry/fearful/disgusted/surprised/neutral；speed/vol/pitch三旋钮；内联拟声 (laughs)、(sighs)；单次上限1万字符，超3000建议流式
ElevenLabs v3：行内方括号标签 [whispers][laughs][sad][shouts] 可堆叠；重音=全大写或[shouts]；每行开头先写情绪标签；拼写必须正确——坏标签会被念出来；v3不支持SSML（<break>→[pause]）；单次合成≥250字符更稳
情感不足五解法：①长句拆短句、情绪转折用省略号 ②分段设参再拼接（常规1.1-1.2倍速、情感戏0.9-1.0+停顿）③重点词加重音/换气标记 ④情绪指令型TTS兜底 ⑤全剧固定音色ID留底+关键段落人工精修` },
  { no: 8, t: `剪辑卡点与字幕规范`, text: `【剪辑卡点与字幕规范】
剪映AI踩点：音频→踩点→自动踩点（节拍I/II）→黄色节拍标记→切换点对齐；配合"智能分段"按台词切镜头；进阶=手动微调让反转对准重拍
字幕：竖屏一行≤8-10字符、最多两行、避开进度条；1080×1920字号约50-70px、位置70%-85%高度；黑体白字黑边，全片统一【社区经验】
节奏时间轴【经验推断】：0-3s钩子 → 5-15s冲突 → 中段递进 → 结尾悬念
色温统一：源头控制（主力镜头同一模型，写实/二次元/3D不混用）→五步质检→剪映"智能调色"/达芬奇统一LUT；光影跳变用局部重绘修复` },
  { no: 9, t: `发布数据基准与投流标尺`, text: `【发布数据基准】
完播率（竖屏）：及格30% / 良好45% / 优秀50-60%+（30%以下基本没流量）
3秒完播（投流素材）：30-40%有起量潜力｜点赞率：及格3%、起量5%+｜评论率：0.5%及格、1%良好
转粉率：1%及格 / 3%良好 / 3-5%优秀、>5%爆款级
起量机制：300-500基础播放 → 完播达标进二级池（约3000）→ 逐级放量；完播是门票，互动/转粉决定能否爆
投流（巨量千川）：ROI≥1.1可跑量、1.15-1.2为及格线；冷启动自动出价跑模型 → 起量后切支付ROI；磁力金牛走可灵生态内循环` },
],

