      emotion: { k: `情绪词`, w: 15, words: `打脸,逆袭,复仇,宠,怒,恨,崩溃,泪,疯,爽,绝,虐` },
      conflict: { k: `冲突/动作词`, w: 15, words: `打,杀,跪,扇,退婚,休,逐出家门,踏,灭,逃,抢,逼` },
