  warning: [
    `收益分化悬殊：头部<1%团队月入10万+；90%尾部月入<5000元，约30%亏损，有新手三个月倒贴6000元`,
    `千次播放收益从60元跌至15-30元；出现1.8亿播放仅结算18万元的真实案例——爆款播放≠爆款收入`,
    `2025年基准（DataEye口径，经核验确认）：上线漫剧60,946部、仅96部破亿（爆款率约0.16%）、64%播放不足100万——立项评估按爆款率而非产能叙事做预算`,
    `2026H1基准（DataEye半年报，澎湃/观察者网/DataEye官网多源转引）：全网AI短剧超22.19万部、破亿1055部（破亿率0.47%）、AI漫剧爆款率不足0.1%——爆款率双口径并列：2025全年漫剧0.16% / 2026H1 AI漫剧<0.1%`,
    `入局前先算"三本账"：单条综合成本、抽卡可用率、万播单价`,
  ],
  compliance: [
    { t: `备案分类分层`, d: `投资≥80万元：总局备案+省级审核+发行许可证；30-80万：省级广电审核；<30万：平台自审。未备案不得上线。2026-04-01起AI漫剧备案新规全面强制（细则以官方为准）。` },
    { t: `AI内容标识与苔花新规`, d: `《人工智能生成合成内容标识办法》2025-09-01施行：显式（画面提示）+隐式（元数据）双标识；《微短剧发展管理办法》2026-09-01施行——统一"苔花"标识（红底金色）与《微短剧发行许可证》同步落地，AI微短剧另有篆体专项标识、AI演员不得伪装真人、明确11项禁止内容；2025.11-2026.3专项整治下架1700余部违规漫剧（AI素材违规670部）。抖音口径（2025-05新规）：任一环节用AI生成须发布时勾选"本视频含有AI生成内容"并在视频显著位置标注**持续≥2秒**（只写简介无效），漏标轻则限流/降权/隐藏、重则封禁——抖音电商2025Q1处置漏标内容80万条；合规标注的AI内容本身不被限流，打击的是漏标而非AI。` },
    { t: `三门票与停更潮`, d: `2026-09-01微短剧新规生效后，"无授权搬运+批量生成+平台分成"流水线被集中治理（小红书漫剧教程收藏2万次未跌、审核退回率反涨）：备案+授权+AI标识是三张入场门票，缺一即遭下架停更。红果治理趋势（潮新闻2026-09-15）：2026Q1下架违规漫剧1718部→低质治理一周3522部→6月单月处罚14357部→8月拦截下架8689部违规AI剧——治理力度逐月升级。` },
    { t: `版权判定`, d: `"接触+实质性相似"三维度：故事情节雷同度、台词表述、人物身份设定；完全一致的错误（如错别字）可作"接触"证据。维权三难：发现难、取证难、赔偿低。` },
    { t: `音色与肖像`, d: `配音演员已开始起诉AI克隆音色侵权——音色授权要留书面凭证；真人形象/声音克隆需明确授权链。` },
    { t: `地方扶持与"政策元年"`, d: `厦门思明区2026-09-07新政：合规大模型API投入（算力租赁/词元/接口订阅）按30%补助、单家企业年度上限300万元；单部有效播放≥2000万次奖2万元；海外合规发行、融入闽台文化元素另有叠加奖励，三项合计单部最高5万元（流媒体网2026-09-30）。杭州上城"黄金十条"（2026-04-16发布，新华网浙江，全省首发AIGC视听专项政策）：精品剧单部最高30万/单企100万、出海单部20万/单企60万、5亿元文化"新三样"基金，首批兑现名单未公开；北京海淀2026年度申报指南开放中：企业最高500万/园区1000万/出海500万/技术创新1000万；朝阳20条（2026-09-11，八方面措施）：视听企业3000余家、2025年营收261.8亿元占全市30.4%；上海"沪8条"最高1000万元支持（细则待核）。36氪：备案新规后全国已有七个城市推出AI漫剧扶持政策；微短剧被写入"十五五"规划（2026-2030）新兴文化产业（Sedaily/路透转引）。` },
    { t: `司法判例与执行面（2026-09增量）`, d: `湖北首例AI短剧著作权案（武汉江岸区法院审结，长江日报/人民网湖北频道2026-09-22）：认定AI辅助创作短剧属著作权法保护的"视听作品"，判盗播方赔偿2万元，首次将"词元（token）消耗"成本纳入赔偿考量，判决已生效——"独创性智力投入"是AI内容确权关键，漫剧版权维权可直接援引。执行面：总局令第16号施行后9月出现集中下架/存量复审，四条硬标准=备案资质/题材红线/AI标识/分集连载（经搜索摘要转述【存疑】）；"清朗"二阶段清理违规内容561万条、查处账号4.9万个；新规版备案号进入实际发放（《天山七曜》获全疆首张，10-2剧短短快报）；广电总局9-17国新办通报：今年以来全网下架违规微短剧6.8万部、处置账号1200多个（前8个月上线43万部、约为2025全年13倍，AI剧占比超九成）；9-4"凡播必审"管理提示；《微短剧发展管理办法》原文无申诉/复核条款，罚则为警告或通报批评、可并处十万元以下罚款（第46条）；9-1北京首发6证5号并启用苔花统一标识（红底金色、一类剧片头）。` },
  ],
