/* 浏览器侧显式挂载：顶层 const 声明不进入 window，挂载后 window.MJ.DB（=window.DB）与 feat 外挂模块才能取到数据层 */
if (typeof window !== 'undefined') window.DB = DB;
if (typeof module !== 'undefined') module.exports = DB;
